#!/usr/bin/env node
// Builds public/preview-frame-bundle.js + public/preview-frame.html: a fully self-contained
// (React + ReactDOM + Babel + LiquidJS + our Polaris shim + JSX/Liquid preview runtimes) static
// bundle for the sandboxed preview iframe used by workspace.tsx's PreviewFrame.
//
// Why a static public/ bundle instead of a normal Next.js route: the iframe is loaded with
// `sandbox="allow-scripts"` and deliberately WITHOUT `allow-same-origin`, so the browser gives it
// an opaque, unique origin no matter what URL it's served from — that's what keeps the untrusted
// generated code it runs from reaching this app's cookies, localStorage, or parent window. But
// Next's dev server unconditionally blocks opaque-origin ("Origin: null") requests to anything
// under /_next/*, with no allowedDevOrigins escape hatch (see block-cross-site-dev.js) — so a
// normal Next.js page can't be loaded from that iframe in dev. Files under /public are served
// as plain static assets, outside that check, so we pre-bundle everything the iframe needs (no
// separate script/chunk requests at all) and serve it from there instead.
//
// Run via `npm run build:preview-frame` (wired into predev/prebuild). Re-run after changing
// src/lib/preview-runtime.tsx, src/lib/liquid-preview-runtime.ts, src/lib/polaris-preview-shim.tsx,
// or scripts/preview-frame-entry.js.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import Babel from "@babel/standalone";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(scriptDir, "..");

function read(relPath) {
  return readFileSync(path.join(root, relPath), "utf8");
}

// Strips `//# sourceMappingURL=...` comments from vendored files — harmless either way, but
// without a real matching .map request behind our inlined bundle it just spams 404s in devtools.
function stripSourceMappingComment(source) {
  return source.replace(/^\/\/#\s*sourceMappingURL=.*$/gm, "");
}

function compileToCommonJs(relPath) {
  const source = read(relPath);
  const result = Babel.transform(source, {
    presets: [["typescript"], ["react", { runtime: "classic" }], ["env", { modules: "commonjs" }]],
    filename: path.basename(relPath),
  });
  return result.code ?? "";
}

function defineModule(name, source) {
  return `define(${JSON.stringify(name)}, function (require, module, exports, process) {\n${source}\n});\n`;
}

const scheduler = stripSourceMappingComment(read("node_modules/scheduler/cjs/scheduler.development.js"));
const react = stripSourceMappingComment(read("node_modules/react/cjs/react.development.js"));
const reactDom = stripSourceMappingComment(read("node_modules/react-dom/cjs/react-dom.development.js"));
const reactDomClient = stripSourceMappingComment(
  read("node_modules/react-dom/cjs/react-dom-client.development.js"),
);
const babelStandalone = stripSourceMappingComment(read("node_modules/@babel/standalone/babel.min.js"));
const liquidStandalone = stripSourceMappingComment(read("node_modules/liquidjs/dist/liquid.browser.umd.js"));
const polarisShimSrc = compileToCommonJs("src/lib/polaris-preview-shim.tsx");
const previewRuntimeSrc = compileToCommonJs("src/lib/preview-runtime.tsx");
const liquidPreviewRuntimeSrc = compileToCommonJs("src/lib/liquid-preview-runtime.ts");
const entryGlue = read("scripts/preview-frame-entry.js");

const bundle = `"use strict";
// GENERATED by scripts/build-preview-frame.mjs — do not edit directly.
(function () {
  var __pfRegistry = {};
  var __pfCache = {};
  function define(name, factory) {
    __pfRegistry[name] = factory;
  }
  function __pfRequire(name) {
    if (__pfCache[name]) return __pfCache[name].exports;
    var factory = __pfRegistry[name];
    if (!factory) throw new Error('Preview frame: unknown module "' + name + '"');
    var mod = { exports: {} };
    __pfCache[name] = mod;
    factory(__pfRequire, mod, mod.exports, { env: { NODE_ENV: "development" } });
    return mod.exports;
  }

${defineModule("scheduler", scheduler)}
${defineModule("react", react)}
${defineModule("react-dom", reactDom)}
${defineModule("react-dom/client", reactDomClient)}
${defineModule("polaris-shim", polarisShimSrc)}
${defineModule("preview-runtime", previewRuntimeSrc)}
${defineModule("liquid-preview-runtime", liquidPreviewRuntimeSrc)}

  var React = __pfRequire("react");
  var ReactDOMClient = __pfRequire("react-dom/client");
  var PolarisShim = __pfRequire("polaris-shim");
  var PreviewRuntime = __pfRequire("preview-runtime");
  var LiquidPreviewRuntime = __pfRequire("liquid-preview-runtime");

${babelStandalone}

  var Babel = globalThis.Babel;

${liquidStandalone}

  var LiquidJSNamespace = globalThis.liquidjs;

${entryGlue}
})();
`;

const html = `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <title>App screen preview</title>
  </head>
  <body style="margin:0">
    <div id="root"></div>
    <div id="liquid-root"></div>
    <script src="/preview-frame-bundle.js"></script>
  </body>
</html>
`;

const publicDir = path.join(root, "public");
mkdirSync(publicDir, { recursive: true });
writeFileSync(path.join(publicDir, "preview-frame-bundle.js"), bundle);
writeFileSync(path.join(publicDir, "preview-frame.html"), html);

console.log(
  `Built public/preview-frame-bundle.js (${(bundle.length / 1024 / 1024).toFixed(1)} MB) and public/preview-frame.html`,
);
